package com.hostelcare.controller;
import com.hostelcare.service.ComplaintService;import com.hostelcare.repository.*;import com.hostelcare.entity.*;import org.springframework.web.bind.annotation.*;import java.security.Principal;import java.util.*;
@RestController @RequestMapping("/api/student") public class StudentController {private final UserRepository users;private final ComplaintService service;private final ComplaintHistoryRepository histories;private final ComplaintAttachmentRepository attachments;private final AssignmentRepository assignments;public StudentController(UserRepository u,ComplaintService s,ComplaintHistoryRepository h,ComplaintAttachmentRepository a,AssignmentRepository as){users=u;service=s;histories=h;attachments=a;assignments=as;} @GetMapping("/profile") public Map<String,Object> profile(Principal p){return ViewMapper.user(users.findByEmail(p.getName()).orElseThrow());} @GetMapping("/complaints") public List<?> complaints(Principal p){return service.mine(p.getName()).stream().map(ViewMapper::complaint).toList();} }
